package vn.phongiot;
import android.app.*;import android.os.*;import android.graphics.Color;import android.text.InputType;import android.widget.*;import org.json.*;import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.*;

public class MainActivity extends Activity {
 EditText host,token;TextView output,status;Handler handler=new Handler(Looper.getMainLooper());ExecutorService executor=Executors.newSingleThreadExecutor();boolean active=false;volatile boolean requesting=false;String url="",key="";
 LinearLayout layout;
 Button button(String text,Runnable action){Button b=new Button(this);b.setText(text);b.setOnClickListener(v->action.run());layout.addView(b);return b;}
 @Override public void onCreate(Bundle b){super.onCreate(b);ScrollView scroll=new ScrollView(this);layout=new LinearLayout(this);layout.setOrientation(LinearLayout.VERTICAL);layout.setPadding(30,35,30,30);layout.setBackgroundColor(Color.rgb(244,248,241));scroll.addView(layout);setContentView(scroll);TextView title=new TextView(this);title.setText("PHÒNG Ở THÔNG MINH");title.setTextSize(23);layout.addView(title);host=new EditText(this);host.setHint("http://IP-LAPTOP:8765");layout.addView(host);token=new EditText(this);token.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);token.setHint("Mã truy cập từ laptop");layout.addView(token);button("Kết nối",()->{url=host.getText().toString().replaceAll("/$","");key=token.getText().toString().trim();active=true;request(null);});status=new TextView(this);layout.addView(status);output=new TextView(this);output.setTextSize(19);output.setPadding(0,25,0,25);layout.addView(output);button("Phòng ngủ",()->post("hardwareId","esp32-room-01"));button("Phòng khách",()->post("hardwareId","esp32-room-02"));button("Chế độ tự động",()->post("mode","auto"));for(String kind:new String[]{"manualFan","led","manualBuzzer"}){String label=kind.equals("manualFan")?"quạt":kind.equals("led")?"đèn":"còi";button("Bật "+label,()->control(kind,true));button("Tắt "+label,()->control(kind,false));}handler.postDelayed(poll,2000);}
 void post(String k,Object v){try{request(new JSONObject().put(k,v));}catch(JSONException e){status.setText(e.toString());}}
 void control(String k,boolean value){try{request(new JSONObject().put("mode","manual").put(k,value));}catch(JSONException e){status.setText(e.toString());}}
 final Runnable poll=new Runnable(){public void run(){if(active)request(null);handler.postDelayed(this,2000);}};
 void request(JSONObject data){if(url.isEmpty()||requesting)return;requesting=true;final String base=url,access=key;executor.execute(()->{HttpURLConnection c=null;try{URL u=new URL(base+(data==null?"/api/status":"/api/settings"));if(!u.getProtocol().matches("https?"))throw new IOException("Chỉ hỗ trợ HTTP/HTTPS");c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(5000);c.setReadTimeout(5000);c.setRequestProperty("Authorization","Bearer "+access);if(data!=null){c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream out=c.getOutputStream()){out.write(data.toString().getBytes(StandardCharsets.UTF_8));}}int code=c.getResponseCode();InputStream input=code<400?c.getInputStream():c.getErrorStream();StringBuilder text=new StringBuilder();try(BufferedReader reader=new BufferedReader(new InputStreamReader(input,StandardCharsets.UTF_8))){String l;while((l=reader.readLine())!=null)text.append(l);}JSONObject p=new JSONObject(text.toString());if(code>=400)throw new IOException(p.optString("error","HTTP "+code));JSONObject d=p.getJSONObject("device");String display=d.getString("id")+"\n\nNhiệt độ: "+d.opt("temperature")+" °C\nĐộ ẩm: "+d.opt("humidity")+" %\nÁnh sáng: "+d.opt("light")+" %\nKhí tương đối: "+d.opt("airQuality")+"\nPIR: "+d.opt("motion")+"\n\nQuạt: "+d.opt("fan")+" | Đèn: "+d.opt("led")+" | Còi: "+d.opt("buzzer");runOnUiThread(()->{output.setText(display);status.setText(d.optBoolean("online")?"Thiết bị trực tuyến":"Thiết bị ngoại tuyến");});}catch(Exception e){runOnUiThread(()->status.setText("Lỗi: "+e.getMessage()));}finally{if(c!=null)c.disconnect();requesting=false;}});}
 @Override protected void onDestroy(){handler.removeCallbacks(poll);executor.shutdownNow();super.onDestroy();}
}
